#!/usr/bin/env node
/**
 * Advisory source-size check with two supported interfaces:
 *   node file-size-guard.mjs --check FILE...
 *   PostToolUse JSON on stdin (Claude file_path or Codex apply_patch command)
 *
 * The hook is deliberately nonblocking. CLI input/tool errors exit 2 and an
 * all-not-applicable CLI run exits 3; size and density advisories exit 0.
 */

import { execFile as execFileCallback } from 'node:child_process';
import { createHash } from 'node:crypto';
import { lstat, mkdir, readFile, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { promisify } from 'node:util';

const execFile = promisify(execFileCallback);
const DEFAULT_THRESHOLD = 500;
const RENOTIFY_GROWTH = 0.20;
const DENSE_MIN_BYTES = 4096;
const DENSE_BYTES_PER_LINE = 240;
const SOURCE_EXTENSIONS = new Set([
  '.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs', '.mts', '.cts',
  '.py', '.go', '.rs', '.java', '.kt', '.rb', '.php', '.swift',
  '.c', '.cc', '.cpp', '.h', '.hpp', '.cs', '.vue', '.svelte',
]);
const SKIP_DIRECTORIES = new Set([
  'node_modules', 'dist', 'build', 'out', 'vendor', 'coverage', '.git',
  '.next', '.nuxt', '.cache', '__pycache__', 'target', 'generated',
]);
const GENERATED_MARKERS = [
  'auto-generated', 'autogenerated', '@generated', 'do not edit',
  'generated file', 'generated by',
];
const GENERATED_NAMES = [
  /\.(?:min|bundle)\.(?:js|mjs|cjs)$/i,
  /(?:^|[._-])generated(?:[._-]|$)/i,
];
const PERMISSION_MODES = new Set(['default', 'acceptEdits', 'plan', 'dontAsk', 'bypassPermissions']);
const GIT_COMMAND = process.platform === 'win32' ? 'git.exe' : 'git';

class InputError extends Error {}

function thresholdFromEnvironment() {
  const raw = process.env.FILE_SIZE_GUARD_THRESHOLD;
  if (raw === undefined || raw === '') return DEFAULT_THRESHOLD;
  if (!/^[1-9]\d*$/.test(raw)) {
    throw new InputError('FILE_SIZE_GUARD_THRESHOLD must be a positive integer');
  }
  return Number(raw);
}

function physicalLines(text) {
  if (text.length === 0) return 0;
  const normalized = text.replaceAll('\r\n', '\n').replaceAll('\r', '\n');
  return (normalized.match(/\n/g)?.length ?? 0) + (normalized.endsWith('\n') ? 0 : 1);
}

function countMatches(text, expression) {
  return [...text.matchAll(expression)].length;
}

function metricsFor(text) {
  const lines = physicalLines(text);
  const bytes = Buffer.byteLength(text, 'utf8');
  const approxTokens = Math.ceil(bytes / 4);
  const denominator = Math.max(lines, 1);
  return {
    lines,
    bytes,
    approxTokens,
    bytesPerLine: Math.round((bytes / denominator) * 10) / 10,
    approxTokensPerLine: Math.round((approxTokens / denominator) * 10) / 10,
    namedUnits: countMatches(
      text,
      /\b(?:function|class|interface|enum|struct|trait|def|fn)\s+[A-Za-z_$][\w$]*|\b(?:const|let|var)\s+[A-Za-z_$][\w$]*\s*=/g,
    ),
    decisionHints: countMatches(text, /\b(?:if|else|switch|case|for|while|catch|match)\b/g),
  };
}

function generatedReason(file, text, scopeRoot) {
  const relative = path.relative(path.resolve(scopeRoot), path.resolve(file));
  const inside = relative && relative !== '..' && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative);
  const parts = inside ? relative.split(path.sep).slice(0, -1).map((part) => part.toLowerCase()) : [];
  const skipped = parts.find((part) => SKIP_DIRECTORIES.has(part));
  if (skipped) return `generated/vendor/build directory ${skipped}`;
  if (GENERATED_NAMES.some((expression) => expression.test(path.basename(file)))) {
    return 'generated or bundled filename';
  }
  const head = text.split(/\r?\n/, 10).join('\n').toLowerCase();
  const marker = GENERATED_MARKERS.find((candidate) => head.includes(candidate));
  return marker ? `generated marker ${marker}` : null;
}

function displayPath(file) {
  const relative = path.relative(process.cwd(), file);
  const shown = relative && !relative.startsWith(`..${path.sep}`) && relative !== '..' ? relative : file;
  return shown.split(path.sep).join('/');
}

function quote(value) {
  return JSON.stringify(String(value));
}

function metricFields(result) {
  if (!result.metrics) return '';
  const value = result.metrics;
  const baseline = result.baseline === null || result.baseline === undefined ? 'unknown' : result.baseline;
  return [
    `lines=${value.lines}`,
    `bytes=${value.bytes}`,
    `approx-tokens=${value.approxTokens}`,
    `bytes-per-line=${value.bytesPerLine}`,
    `approx-tokens-per-line=${value.approxTokensPerLine}`,
    `named-unit-hints=${value.namedUnits}`,
    `decision-hints=${value.decisionHints}`,
    `head-lines=${baseline}`,
  ].join(' ');
}

function formatResult(result) {
  const common = `file=${quote(result.file)} reason=${quote(result.reason)}`;
  const metrics = metricFields(result);
  const notification = result.notification ? ` notification=${result.notification}` : '';
  const guidance = result.status === 'ADVISORY'
    ? ' guidance="Decompose by responsibility only when it fits the task; cohesive or declarative files can be justified. This is not a maintainability verdict."'
    : '';
  return `${result.status} ${common}${metrics ? ` ${metrics}` : ''}${notification}${guidance}`;
}

function summaryFor(results) {
  const counts = Object.fromEntries(
    ['APPLICABLE-PASS', 'ADVISORY', 'NOT-APPLICABLE', 'ERROR']
      .map((status) => [status, results.filter((result) => result.status === status).length]),
  );
  let status = 'NOT-APPLICABLE';
  let reason = 'every requested file was outside the supported source scope';
  if (counts.ERROR) {
    status = 'ERROR';
    reason = 'one or more files could not be checked';
  } else if (counts.ADVISORY) {
    status = 'ADVISORY';
    reason = 'one or more files crossed an advisory growth or density signal';
  } else if (counts['APPLICABLE-PASS']) {
    status = 'APPLICABLE-PASS';
    reason = 'every applicable file was checked without a new advisory signal';
  }
  return `${status} summary checked=${counts['APPLICABLE-PASS'] + counts.ADVISORY} advisory=${counts.ADVISORY} not-applicable=${counts['NOT-APPLICABLE']} errors=${counts.ERROR} reason=${quote(reason)}`;
}

async function gitHeadLines(file) {
  const directory = path.dirname(file);
  try {
    const { stdout } = await execFile(GIT_COMMAND, ['rev-parse', '--is-inside-work-tree'], {
      cwd: directory, encoding: 'utf8', windowsHide: true, timeout: 2_000,
    });
    if (stdout.trim() !== 'true') return null;
  } catch {
    return null;
  }
  try {
    const { stdout } = await execFile(GIT_COMMAND, ['show', `HEAD:./${path.basename(file)}`], {
      cwd: directory, encoding: 'buffer', windowsHide: true, timeout: 2_000, maxBuffer: 32 * 1024 * 1024,
    });
    return physicalLines(stdout.toString('utf8'));
  } catch {
    return 0;
  }
}

function stateFile(sessionId) {
  const digest = createHash('sha256').update(sessionId).digest('hex').slice(0, 20);
  const directory = process.env.FILE_SIZE_GUARD_STATE_DIR || tmpdir();
  return path.join(directory, `aer-file-size-guard-${digest}.json`);
}

async function loadState(sessionId) {
  const file = stateFile(sessionId);
  try {
    const parsed = JSON.parse(await readFile(file, 'utf8'));
    return { file, state: { seen: parsed.seen ?? {}, nagged: parsed.nagged ?? {} } };
  } catch {
    return { file, state: { seen: {}, nagged: {} } };
  }
}

async function saveState(file, state) {
  try {
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, `${JSON.stringify(state)}\n`, 'utf8');
  } catch {
    // Advisory state must never make the hook block real work.
  }
}

async function inspectFile(file, { threshold, hook, stateContext, scopeRoot, newFile = false }) {
  const absolute = path.resolve(file);
  const shown = displayPath(absolute);
  let information;
  try {
    information = await lstat(absolute);
  } catch (error) {
    if (hook && error.code === 'ENOENT') {
      return { status: 'NOT-APPLICABLE', file: shown, reason: 'file no longer exists after the completed edit' };
    }
    return { status: 'ERROR', file: shown, reason: `cannot inspect file: ${error.message}` };
  }
  if (information.isSymbolicLink()) {
    return { status: 'NOT-APPLICABLE', file: shown, reason: 'symbolic links are not scanned' };
  }
  if (!information.isFile()) {
    return { status: 'ERROR', file: shown, reason: 'path is not a regular file' };
  }
  const extension = path.extname(absolute).toLowerCase();
  if (!SOURCE_EXTENSIONS.has(extension)) {
    return { status: 'NOT-APPLICABLE', file: shown, reason: `unsupported declarative or non-source extension ${extension || '(none)'}` };
  }

  let text;
  try {
    text = await readFile(absolute, 'utf8');
  } catch (error) {
    return { status: 'ERROR', file: shown, reason: `cannot read file: ${error.message}` };
  }
  const generated = generatedReason(absolute, text, scopeRoot);
  if (generated) return { status: 'NOT-APPLICABLE', file: shown, reason: generated };

  const metrics = metricsFor(text);
  let baseline = newFile ? 0 : await gitHeadLines(absolute);
  const key = absolute.split(path.sep).join('/');
  let stateChanged = false;
  if (hook && newFile && stateContext.state.seen[key] === undefined) {
    // Preserve the first observed Add metrics so a later Update in a
    // non-Git workspace can still measure growth from the creation event.
    stateContext.state.seen[key] = metrics.lines;
    stateChanged = true;
  }
  if (hook && baseline === null) {
    if (stateContext.state.seen[key] === undefined) {
      stateContext.state.seen[key] = metrics.lines;
      stateChanged = true;
    }
    baseline = stateContext.state.seen[key];
  }

  const overLines = metrics.lines > threshold;
  const dense = metrics.bytes >= DENSE_MIN_BYTES && metrics.bytesPerLine >= DENSE_BYTES_PER_LINE;
  const reasons = [];
  if (overLines) {
    if (baseline === null) {
      reasons.push(`current size exceeds the ${threshold}-line advisory threshold; no Git baseline is available`);
    } else if (baseline <= threshold) {
      reasons.push(`grew from ${baseline} to ${metrics.lines} lines, crossing the ${threshold}-line advisory threshold`);
    } else if (metrics.lines - baseline >= Math.max(100, Math.ceil(baseline * RENOTIFY_GROWTH))) {
      reasons.push(`was ${baseline} lines at Git HEAD and grew to ${metrics.lines} lines`);
    }
  }
  if (dense) {
    reasons.push(`dense short-file signal is ${metrics.bytesPerLine} authored bytes per line across ${metrics.bytes} bytes`);
  }

  if (!reasons.length) {
    if (hook && stateContext.state.nagged[key] !== undefined) {
      delete stateContext.state.nagged[key];
      stateChanged = true;
    }
    if (stateChanged) await saveState(stateContext.file, stateContext.state);
    const reason = overLines && baseline !== null && baseline > threshold
      ? `pre-existing large file has not grown by max(100 lines, 20%) from its ${baseline}-line Git baseline`
      : 'physical size and formatting-resistant density signals are below advisory conditions';
    return { status: 'APPLICABLE-PASS', file: shown, reason, metrics, baseline };
  }

  let notification = 'emitted';
  if (hook) {
    const previous = stateContext.state.nagged[key];
    const renotify = previous === undefined
      || metrics.lines >= Math.ceil(previous.lines * (1 + RENOTIFY_GROWTH))
      || metrics.bytes >= Math.ceil(previous.bytes * (1 + RENOTIFY_GROWTH));
    if (renotify) {
      stateContext.state.nagged[key] = { lines: metrics.lines, bytes: metrics.bytes };
      stateChanged = true;
    } else {
      notification = 'suppressed-until-20%-growth';
    }
    if (stateChanged) await saveState(stateContext.file, stateContext.state);
  }
  return { status: 'ADVISORY', file: shown, reason: reasons.join('; '), metrics, baseline, notification };
}

function parseCli(arguments_) {
  if (arguments_.length === 1 && arguments_[0] === '--help') return { help: true };
  if (arguments_[0] !== '--check') {
    throw new InputError('expected --check FILE... or --help');
  }
  let files = arguments_.slice(1);
  const acceptsOptionLikeNames = files[0] === '--';
  if (acceptsOptionLikeNames) files = files.slice(1);
  if (!files.length) throw new InputError('--check requires at least one file');
  const option = acceptsOptionLikeNames ? null : files.find((file) => file.startsWith('-'));
  if (option) throw new InputError(`unknown argument: ${option}; use -- before a filename beginning with -`);
  return { files };
}

function helpText() {
  return `NOT-APPLICABLE mode=help reason="help displayed; no files were checked"
Usage:
  node agent-rules/tools/file-size-guard.mjs --check FILE...
  node agent-rules/tools/file-size-guard.mjs --help

Examples:
  node agent-rules/tools/file-size-guard.mjs --check src/app.js src/view.tsx
  PowerShell: $env:FILE_SIZE_GUARD_THRESHOLD='650'; node agent-rules/tools/file-size-guard.mjs --check src/legacy.js
  POSIX: FILE_SIZE_GUARD_THRESHOLD=650 node agent-rules/tools/file-size-guard.mjs --check src/legacy.js

Results: APPLICABLE-PASS, ADVISORY, NOT-APPLICABLE with a reason, or ERROR.
CLI exits: 0 checked (including advisory), 2 input/tool error, 3 all inputs not applicable.
With no arguments, one PostToolUse JSON object is read from stdin. Hook mode
accepts Claude tool_input.file_path and Codex apply_patch tool_input.command,
emits JSON context, and remains nonblocking even when hook input is malformed.

The default 500-line signal is contextual, not a maintainability verdict.
The density signal uses authored UTF-8 bytes and an approximate four-bytes-per-
token metric; declaration and decision counts are lexical hints, not complexity
measurements. Generated, bundled, vendor/build, and non-source declarative files
are not applicable. Git HEAD supplies the baseline; FILE_SIZE_GUARD_THRESHOLD is
the repository/CI override. No strict mode is enabled by default.`;
}

async function readStandardInput() {
  process.stdin.setEncoding('utf8');
  let input = '';
  for await (const chunk of process.stdin) input += chunk;
  return input;
}

function pathsFromHook(payload) {
  const input = payload.tool_input;
  if (payload.tool_name === 'apply_patch') {
    const candidates = [];
    for (const match of input.command.matchAll(/^\*\*\* (Add|Update|Delete) File:\s*(.+?)\s*$/gm)) {
      candidates.push({ path: match[2], operation: match[1].toLowerCase() });
    }
    for (const match of input.command.matchAll(/^\*\*\* Move to:\s*(.+?)\s*$/gm)) {
      candidates.push({ path: match[1], operation: 'move' });
    }
    const unique = new Map();
    for (const candidate of candidates) {
      const previous = unique.get(candidate.path);
      if (!previous || candidate.operation === 'add') unique.set(candidate.path, candidate);
    }
    return [...unique.values()];
  }
  return [{ path: input.file_path.trim(), operation: 'edit' }];
}

function hookOutput(message, { modelContext = false } = {}) {
  if (!modelContext) return JSON.stringify({ systemMessage: `file-size-guard: ${message}` });
  return JSON.stringify({
    hookSpecificOutput: {
      hookEventName: 'PostToolUse',
      additionalContext: `file-size-guard:\n${message}`,
    },
  });
}

async function runHook(raw) {
  let payload;
  try {
    payload = JSON.parse(raw);
  } catch (error) {
    console.log(hookOutput(`ERROR reason=${quote(`malformed PostToolUse JSON: ${error.message}`)}`));
    return 0;
  }
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    console.log(hookOutput('ERROR reason="PostToolUse payload must be a JSON object"'));
    return 0;
  }
  for (const field of ['session_id', 'cwd', 'permission_mode', 'hook_event_name', 'tool_name', 'tool_use_id']) {
    if (typeof payload[field] !== 'string' || !payload[field].trim()) {
      console.log(hookOutput(`ERROR reason=${quote(`PostToolUse payload requires non-empty ${field}`)}`));
      return 0;
    }
  }
  if (!PERMISSION_MODES.has(payload.permission_mode)) {
    console.log(hookOutput(`ERROR reason=${quote(`PostToolUse payload permission_mode must be one of ${[...PERMISSION_MODES].join(', ')}`)}`));
    return 0;
  }
  if (!Object.hasOwn(payload, 'transcript_path')
      || (payload.transcript_path !== null && (typeof payload.transcript_path !== 'string' || !payload.transcript_path.trim()))) {
    console.log(hookOutput('ERROR reason="PostToolUse payload requires transcript_path as a non-empty string or null"'));
    return 0;
  }
  if (!Object.hasOwn(payload, 'tool_response')) {
    console.log(hookOutput('ERROR reason="PostToolUse payload requires tool_response (any JSON value)"'));
    return 0;
  }
  if (payload.hook_event_name !== 'PostToolUse') {
    console.log(hookOutput(`NOT-APPLICABLE reason=${quote(`hook event is ${payload.hook_event_name}, not PostToolUse`)}`));
    return 0;
  }
  if (!payload.tool_input || typeof payload.tool_input !== 'object' || Array.isArray(payload.tool_input)) {
    console.log(hookOutput('ERROR reason="PostToolUse payload requires an object tool_input"'));
    return 0;
  }
  if (payload.tool_name === 'apply_patch') {
    for (const field of ['turn_id', 'model']) {
      if (typeof payload[field] !== 'string' || !payload[field].trim()) {
        console.log(hookOutput(`ERROR reason=${quote(`Codex PostToolUse payload requires non-empty ${field}`)}`));
        return 0;
      }
    }
    if (typeof payload.tool_input.command !== 'string' || !payload.tool_input.command.trim()) {
      console.log(hookOutput('ERROR reason="Codex apply_patch input requires a non-empty command"'));
      return 0;
    }
  } else if (payload.tool_name === 'Edit' || payload.tool_name === 'Write') {
    if (typeof payload.tool_input.file_path !== 'string' || !payload.tool_input.file_path.trim()) {
      console.log(hookOutput(`ERROR reason=${quote(`Claude ${payload.tool_name} input requires a non-empty file_path`)}`));
      return 0;
    }
  } else {
    console.log(hookOutput(`NOT-APPLICABLE reason=${quote(`unsupported PostToolUse tool ${payload.tool_name}`)}`));
    return 0;
  }

  let threshold;
  try {
    threshold = thresholdFromEnvironment();
  } catch (error) {
    console.log(hookOutput(`ERROR reason=${quote(error.message)}`));
    return 0;
  }
  const candidates = pathsFromHook(payload);
  if (!candidates.length) {
    console.log(hookOutput('NOT-APPLICABLE reason="tool input did not identify a Claude file_path or Codex apply_patch file"'));
    return 0;
  }
  const base = payload.cwd;
  const sessionId = payload.session_id;
  const stateContext = await loadState(sessionId);
  const results = [];
  for (const candidate of candidates) {
    const file = path.isAbsolute(candidate.path) ? candidate.path : path.resolve(base, candidate.path);
    results.push(await inspectFile(file, {
      threshold, hook: true, stateContext, scopeRoot: base, newFile: candidate.operation === 'add',
    }));
  }
  const message = [...results.map(formatResult), summaryFor(results)].join('\n');
  const modelContext = results.some((result) => result.status === 'ADVISORY' && result.notification === 'emitted');
  console.log(hookOutput(message, { modelContext }));
  return 0;
}

async function runCli(arguments_) {
  let parsed;
  try {
    parsed = parseCli(arguments_);
  } catch (error) {
    console.error(`ERROR reason=${quote(error.message)}`);
    return 2;
  }
  if (parsed.help) {
    console.log(helpText());
    return 0;
  }
  let threshold;
  try {
    threshold = thresholdFromEnvironment();
  } catch (error) {
    console.error(`ERROR reason=${quote(error.message)}`);
    return 2;
  }
  const stateContext = { file: '', state: { seen: {}, nagged: {} } };
  const results = [];
  for (const file of parsed.files) {
    results.push(await inspectFile(file, {
      threshold, hook: false, stateContext, scopeRoot: process.cwd(),
    }));
  }
  for (const result of results) console.log(formatResult(result));
  console.log(summaryFor(results));
  if (results.some((result) => result.status === 'ERROR')) return 2;
  if (results.every((result) => result.status === 'NOT-APPLICABLE')) return 3;
  return 0;
}

async function main() {
  const arguments_ = process.argv.slice(2);
  if (arguments_.length) return runCli(arguments_);
  if (process.stdin.isTTY) {
    console.error('ERROR reason="expected --check FILE..., --help, or PostToolUse JSON on stdin"');
    return 2;
  }
  const raw = await readStandardInput();
  return runHook(raw);
}

main()
  .then((code) => { process.exitCode = code; })
  .catch((error) => {
    if (process.argv.length === 2 && !process.stdin.isTTY) {
      console.log(hookOutput(`ERROR reason=${quote(`unexpected hook failure: ${error.message}`)}`));
      process.exitCode = 0;
    } else {
      console.error(`ERROR reason=${quote(error.message)}`);
      process.exitCode = 2;
    }
  });
